  _neonSign(x, z, y, text, rng) {
    const color = rng.pick(['#ff2f8e', '#38e8ff', '#ffd166', '#7dff9c', '#ff7a4d', '#c38bff']);
    const tex = textTexture(text, color, 'rgba(8,6,14,.92)', rng.r() > 0.5 ? 'LEONIDA' : '');
