    const tv = new THREE.Mesh(new THREE.PlaneGeometry(4, 2.2), new THREE.MeshBasicMaterial({ color: 0x1b3f60 })); tv.position.set(0.2, 2.4, -7.0); room.add(tv);
    const tvGlow = new THREE.Mesh(new THREE.PlaneGeometry(3.9, 2.1), new THREE.MeshBasicMaterial({ color: 0x38e8ff, transparent: true, opacity: 0.15 })); tvGlow.position.set(0.2, 2.4, -6.98); room.add(tvGlow);
    const couch = new THREE.Mesh(new THREE.BoxGeometry(5, 1.2, 1.8), new THREE.MeshStandardMaterial({ color: 0x4b3a52 })); couch.position.set(0, 0.9, -4.6); room.add(couch);
    const table = new THREE.Mesh(new THREE.CylinderGeometry(1.3, 1.2, 0.15, 12), new THREE.MeshStandardMaterial({ color: 0x3a2a24 })); table.position.set(0.2, 1.25, -1.8); room.add(table);
    const light = new THREE.PointLight(0xffbf8a, 18, 22, 2); light.position.set(0, 3.6, 0); room.add(light);
    const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.28, 8, 6), new THREE.MeshBasicMaterial({ color: 0xffd9a0 })); lamp.position.set(0, 3.6, 0); room.add(lamp);
    const bag = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.7, 1.7), new THREE.MeshStandardMaterial({ color: 0x2a2a2a, roughness: 0.9 })); bag.position.set(3.2, 1.7, -1.6); room.add(bag);
    room.visible = false;
    this.interior = { group: room, front: { x: 1600, z: 1607.5 }, back: { x: 1600, z: 1592.5 }, center: { x: 1600, z: 1600 } };
    this.scene.add(room);
  }

  // ---------------------------------------------------------------- helpers
  isInsideBuilding(x, z, pad = 0) {
    for (const c of this.colliders) {
      if (c.h < 0.8) continue;
      if (x > c.minX - pad && x < c.maxX + pad && z > c.minZ - pad && z < c.maxZ + pad) return true;
    }
    return false;
  }

  lineBlocked(x1, z1, x2, z2) {
    const steps = 7;
    for (let i = 1; i < steps; i++) {
      const t = i / steps;
      if (this.isInsideBuilding(lerp(x1, x2, t), lerp(z1, z2, t), 0.2)) return true;
    }
    return false;
  }

  collideCircle(pos, radius) {
    let hit = false;
    for (const c of this.colliders) {
      if (c.h < 0.5) continue;
      const cx = clamp(pos.x, c.minX, c.maxX), cz = clamp(pos.z, c.minZ, c.maxZ);
      let dx = pos.x - cx, dz = pos.z - cz;
      const d2 = dx * dx + dz * dz;
      if (d2 < radius * radius) {
        let d = Math.sqrt(d2);
        if (d < 0.0001) { dx = pos.x - (c.minX + c.maxX) / 2; dz = pos.z - (c.minZ + c.maxZ) / 2; d = Math.hypot(dx, dz) || 1; }
        const push = radius - d;
        pos.x += (dx / d) * push; pos.z += (dz / d) * push;
        hit = true;
      }
    }
    // island edge
    const r = Math.hypot(pos.x, pos.z);
    if (r > CITY.beachR - 4) {
      const k = (CITY.beachR - 4) / r;
      pos.x *= k; pos.z *= k; hit = true;
    }
    return hit;
  }

  districtAt(x, z) {
    if (Math.hypot(x - POI.motel.x, z - POI.motel.z) < 130) return 'PALM SHADE';
    if (x < -250) return 'PORT GELLHORN';
    if (z > 300) return 'LEONIDA KEYS';
    if (x > 230) return 'OCEAN BEACH';
    if (Math.abs(x) < 180 && Math.abs(z) < 200) return 'DOWNTOWN VICE CITY';
    return 'VICE CITY';
  }

  setWeather(mode) {
    const w = this.weather;
    w.mode = mode;
    if (mode === 'clear') { w.targetRain = 0; w.wind = 0.55; w.timer = 70 + Math.random() * 60; }
    if (mode === 'cloudy') { w.targetRain = 0; w.wind = 0.9; w.timer = 45 + Math.random() * 50; }
    if (mode === 'rain') { w.targetRain = 0.7; w.wind = 1.15; w.timer = 60 + Math.random() * 50; }
    if (mode === 'storm') { w.targetRain = 1; w.wind = 2.1; w.timer = 45 + Math.random() * 40; }
  }

  // ---------------------------------------------------------------- update
  update(dt, camera, focusActive, game) {
    this.time += dt;
    this.cameraPos.copy(camera.position);
    const w = this.weather;

    // weather state machine
    w.timer -= dt;
    if (w.timer <= 0) {
      const modes = ['clear', 'clear', 'cloudy', 'rain', 'storm'];
      let next = modes[Math.floor(Math.random() * modes.length)];
      if (next === w.mode) next = 'cloudy';
      this.setWeather(next);
      game?.onWeatherChange?.(next);
    }
    w.rain += (w.targetRain - w.rain) * Math.min(1, dt * 0.35);
    if (w.rain > 0.01) w.wetness = Math.min(1, w.wetness + dt * 0.06 * w.rain);
    else w.wetness = Math.max(0, w.wetness - dt * 0.012);
    w.wind += ((0.55 + w.rain * 1.5) - w.wind) * Math.min(1, dt * 0.4);
    w.flash = Math.max(0, w.flash - dt * 4.5);
    if (w.rain > 0.55) {
      w.lightningTimer -= dt;
      if (w.lightningTimer <= 0) {
        w.lightningTimer = 6 + Math.random() * 12;
        w.flash = 1;
        if (game?.audio) game.audio.thunder();
      }
    }

    // day-night
    this.hour = (this.hour + (24 / this.dayLength) * dt) % 24;
    const t = this.hour / 24;
    const sunEl = Math.sin((t - 0.25) * Math.PI * 2); // +1 noon
    const sunAz = t * Math.PI * 2;
    const sunDir = new THREE.Vector3(Math.cos(sunAz) * Math.cos(sunEl * 0.8), sunEl, Math.sin(sunAz) * Math.cos(sunEl * 0.8)).normalize();
    const daylight = smooth(-0.12, 0.22, sunEl);
    const dusk = Math.max(0, 1 - Math.abs(sunEl) * 3.2);
    this.nightFactor = 1 - daylight;

    const dayTop = new THREE.Color(0x3f79b8), dayMid = new THREE.Color(0x9cc0dd), dayBot = new THREE.Color(0xffdfba);
    const duskTop = new THREE.Color(0x241a44), duskMid = new THREE.Color(0x7c3d6a), duskBot = new THREE.Color(0xff9a6a);
    const nightTop = new THREE.Color(0x040610), nightMid = new THREE.Color(0x0b1026), nightBot = new THREE.Color(0x1d2038);
    const top = nightTop.clone().lerp(dayTop, daylight).lerp(duskTop, dusk * 0.7);
    const mid = nightMid.clone().lerp(dayMid, daylight).lerp(duskMid, dusk * 0.75);
    const bot = nightBot.clone().lerp(dayBot, daylight).lerp(duskBot, dusk * 0.85);
    this.skyUniforms.top.value.copy(top);
    this.skyUniforms.mid.value.copy(mid);
    this.skyUniforms.bottom.value.copy(bot);
    this.skyUniforms.sunDir.value.copy(sunDir);
    this.skyUniforms.night.value = this.nightFactor;

    const fogCol = bot.clone().lerp(mid, 0.4);
    this.scene.fog.color.copy(fogCol);
    this.scene.fog.density = 0.0014 + w.rain * 0.0025;
    this.oceanUniforms.sky.value.copy(fogCol);
    this.oceanUniforms.time.value = this.time;
    this.oceanUniforms.sun.value.copy(sunDir);

    this.sun.position.copy(sunDir).multiplyScalar(320);
    this.sun.position.y = Math.max(30, this.sun.position.y);
    this.sun.intensity = lerp(0.25, 2.35, daylight) * (1 - w.rain * 0.55) + 1.5 * w.flash;
    this.sun.color.copy(new THREE.Color(0xff9a63).lerp(new THREE.Color(0xfff0d6), daylight));
    this.sun.target.position.set(this.cameraPos.x, 0, this.cameraPos.z);
    this.hemi.intensity = lerp(0.22, 0.72, daylight) * (1 - w.rain * 0.25);
    this.hemi.color.copy(new THREE.Color(0x223055).lerp(new THREE.Color(0xa8d2ff), daylight));
    this.hemi.groundColor.copy(new THREE.Color(0x16121c).lerp(new THREE.Color(0x5b4a3a), daylight));
    this.moon.intensity = this.nightFactor * 0.28;
    this.sky.position.copy(camera.position);
    this.stars.position.copy(camera.position);
    this.starMat.opacity = this.nightFactor * 0.9;
    this.sunSprite.position.copy(camera.position).add(sunDir.clone().multiplyScalar(950));
    this.sunSprite.material.opacity = clamp(sunEl * 2.5, 0, 0.85);
    this.sunSprite.material.color.copy(new THREE.Color(0xffb070).lerp(new THREE.Color(0xfff4d0), daylight));
    this.sunSprite.scale.setScalar(lerp(70, 150, clamp(sunEl, 0, 1)));

    const night = this.nightFactor;
    this.buildingMat.emissiveIntensity = lerp(0.12, 1.5, night) + dusk * 0.35;
    this.bulbMat.emissiveIntensity = lerp(0.1, 2.2, night);
    if (this.neonLights) this.neonLights.forEach((l, i) => { l.intensity = (i < 2 ? 10 : 7) * (0.35 + night * 1.1); });

    // wet streets
    for (const sm of this.streetMaterials) {
      const k = w.wetness;
      sm.mat.roughness = lerp(sm.rough[0], sm.rough[1], k);
      sm.mat.color.copy(sm.baseColor).lerp(sm.wetColor, k * 0.75);
    }
    this.puddleMat.opacity = w.wetness * 0.8;

    // vegetation wind
    const wind = w.wind;
    for (const p of this.windObjects) {
      const ph = p.userData.phase + this.time;
      p.userData.crown.rotation.z = Math.sin(ph * 1.1) * 0.055 * wind;
      p.userData.crown.rotation.x = Math.cos(ph * 0.8) * 0.04 * wind;
    }

    // clouds
    for (let i = 0; i < this.clouds.length; i++) {
      const c = this.clouds[i];
      c.position.x += dt * 2.2 * wind * (0.6 + (i % 3) * 0.15);
      if (c.position.x - this.cameraPos.x > 900) c.position.x = this.cameraPos.x - 900;
      c.position.z += Math.sin(this.time * 0.05 + i) * dt * 0.6;
      c.material.opacity = (w.mode === 'storm' ? 0.72 : w.mode === 'rain' ? 0.55 : w.mode === 'cloudy' ? 0.4 : 0.22) * (0.5 + this.rng.r() * 0.02);
      c.material.color.setHex(w.mode === 'storm' ? 0x4a4d5e : w.mode === 'rain' ? 0x7b8296 : 0xffffff);
    }

    // rain particles
    this.rain.visible = w.rain > 0.02;
    if (this.rain.visible) {
      const pos = this.rain.geometry.attributes.position.array;
      const sp = this.rainData.speeds;
      const cx = camera.position.x, cy = camera.position.y, cz = camera.position.z;
      const fall = 0.9 + w.rain;
      for (let i = 0; i < this.rainData.count; i++) {
        pos[i * 3 + 1] -= sp[i] * dt * fall;
        pos[i * 3] += wind * 4.5 * dt;
        pos[i * 3 + 2] += wind * 1.5 * dt;
        if (pos[i * 3 + 1] < cy - 6) {
          pos[i * 3] = cx + (Math.random() - 0.5) * 110;
          pos[i * 3 + 1] = cy + 38 + Math.random() * 12;
          pos[i * 3 + 2] = cz + (Math.random() - 0.5) * 110;
        }
        if (Math.abs(pos[i * 3] - cx) > 70) pos[i * 3] = cx + (Math.random() - 0.5) * 110;
        if (Math.abs(pos[i * 3 + 2] - cz) > 70) pos[i * 3 + 2] = cz + (Math.random() - 0.5) * 110;
      }
      this.rain.geometry.attributes.position.needsUpdate = true;
      this.rainMat.opacity = w.rain * 0.62;
    }
    if (game?.audio) game.audio.setRain(w.rain);

    // lightning flash light
    if (w.flash > 0.01) this.hemi.intensity += w.flash * 2.5;

    // camera-facing visibility of interior
    this.sky.visible = !this.interiorActive;
    if (this.interiorActive) {
      this.scene.fog.density = 0.0;
    }
  }

  clockString() {
    const h = Math.floor(this.hour), m = Math.floor((this.hour % 1) * 60);
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
  }

  weatherLabel() {
    const w = this.weather;
    if (w.mode === 'storm') return 'HURRICANE WARNING';
    if (w.mode === 'rain') return 'TROPICAL RAIN';
    if (w.mode === 'cloudy') return 'OVERCAST';
    return this.nightFactor > 0.5 ? 'CLEAR NIGHT' : 'CLEAR';
  }

  // ---------------------------------------------------------------- radar map
  _buildMapCanvas() {
    const S = 2048, span = 1400;
    const c = document.createElement('canvas'); c.width = c.height = S;
    const g = c.getContext('2d');
    const sx = S / span, cx = S / 2;
    g.fillStyle = '#0a1a26'; g.fillRect(0, 0, S, S);
    g.fillStyle = '#1a2a33';
    g.beginPath(); g.arc(cx, cx, 660 * sx, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#2f2b36';
    g.beginPath(); g.arc(cx, cx, 500 * sx, 0, Math.PI * 2); g.fill();
    // roads
    g.strokeStyle = '#4b4756'; g.lineWidth = 14 * sx;
    for (let i = CITY.gridMin; i <= CITY.gridMax + 1; i++) {
      const p = cx + i * CITY.road * sx;
      g.beginPath(); g.moveTo(p, cx + (CITY.gridMin * CITY.road) * sx); g.lineTo(p, cx + ((CITY.gridMax + 1) * CITY.road) * sx); g.stroke();
      g.beginPath(); g.moveTo(cx + (CITY.gridMin * CITY.road) * sx, p); g.lineTo(cx + ((CITY.gridMax + 1) * CITY.road) * sx, p); g.stroke();
    }
    // blocks
    for (let gx = CITY.gridMin; gx <= CITY.gridMax; gx++) {
      for (let gz = CITY.gridMin; gz <= CITY.gridMax; gz++) {
        const x = cx + (gx * CITY.road + 40) * sx, z = cx + (gz * CITY.road + 40) * sx;
        g.fillStyle = gx < -2 ? '#4c4a42' : gx > 3 ? '#5c464e' : '#3f3b4b';
        g.fillRect(x - 30 * sx, z - 30 * sx, 60 * sx, 60 * sx);
      }
    }
    // POI
    const poiCol = { motel: '#ff5da8', gas: '#ffd166', pawn: '#7dff9c', bank: '#38e8ff', store: '#ff9c5b', hospital: '#ff6b6b', charger: '#38e8ff' };
    for (const k in POI) {
      g.fillStyle = poiCol[k] || '#fff';
      const x = cx + POI[k].x * sx, z = cx + POI[k].z * sx;
      g.fillRect(x - 9, z - 9, 18, 18);
      g.strokeStyle = 'rgba(0,0,0,.6)'; g.lineWidth = 3; g.strokeRect(x - 9, z - 9, 18, 18);
    }
    this.mapCanvas = c; this.mapScale = sx; this.mapCenter = cx;
  }

  drawRadar(ctx, x, z, heading, entities, marker) {
    const W = ctx.canvas.width, R = W / 2;
    const range = 115; // world meters across radius
    const pxPerM = R / range;
    ctx.clearRect(0, 0, W, W);
    ctx.save();
    ctx.beginPath(); ctx.arc(R, R, R, 0, Math.PI * 2); ctx.clip();
    ctx.fillStyle = '#0a1a26'; ctx.fillRect(0, 0, W, W);
    const mapPx = this.mapScale / pxPerM;
    const cxMap = this.mapCenter + x * this.mapScale;
    const czMap = this.mapCenter + z * this.mapScale;
    ctx.drawImage(this.mapCanvas, cxMap - R * mapPx, czMap - R * mapPx, R * 2 * mapPx, R * 2 * mapPx, 0, 0, W, W);
    // darken
    ctx.fillStyle = 'rgba(4,6,12,.18)'; ctx.fillRect(0, 0, W, W);
    const toScreen = (wx, wz) => [R + (wx - x) * pxPerM, R + (wz - z) * pxPerM];
    // marker
    if (marker) {
      const [mx, my] = toScreen(marker.x, marker.z);
      ctx.fillStyle = '#ffd166';
      ctx.beginPath(); ctx.moveTo(mx, my - 9); ctx.lineTo(mx + 7, my + 5); ctx.lineTo(mx - 7, my + 5); ctx.closePath(); ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,.5)'; ctx.lineWidth = 2; ctx.stroke();
    }
    // entities
    for (const e of entities) {
      const [ex, ey] = toScreen(e.x, e.z);
      if (Math.hypot(ex - R, ey - R) > R - 4) continue;
      if (e.type === 'police') {
        ctx.fillStyle = e.flash ? '#ffffff' : '#ff3b46';
        ctx.beginPath(); ctx.arc(ex, ey, 5, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = e.flash ? '#ff3b46' : '#ffffff'; ctx.lineWidth = 1.5; ctx.stroke();
      } else if (e.type === 'personal') {
        ctx.fillStyle = '#38e8ff'; ctx.fillRect(ex - 4, ey - 4, 8, 8);
      } else if (e.type === 'partner') {
        ctx.fillStyle = '#ffd166'; ctx.beginPath(); ctx.arc(ex, ey, 4, 0, Math.PI * 2); ctx.fill();
      } else if (e.type === 'enemy') {
        ctx.fillStyle = '#ff6b6b'; ctx.beginPath(); ctx.arc(ex, ey, 3.5, 0, Math.PI * 2); ctx.fill();
      } else if (e.type === 'poi') {
        ctx.fillStyle = e.color || '#7dff9c'; ctx.fillRect(ex - 3, ey - 3, 6, 6);
      }
    }
    // player arrow
    ctx.save();
    ctx.translate(R, R); ctx.rotate(heading);
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(7, 8); ctx.lineTo(0, 4); ctx.lineTo(-7, 8); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = '#ff2f8e'; ctx.lineWidth = 2; ctx.stroke();
    ctx.restore();
    ctx.restore();
    // north tick
    ctx.fillStyle = 'rgba(56,232,255,.9)'; ctx.font = 'bold 11px Arial'; ctx.textAlign = 'center'; ctx.fillText('N', R, 16);
  }

  setInterior(active) {
    this.interiorActive = active;
    this.interior.group.visible = active;
    this.ocean.visible = !active;
    this.sand.visible = !active;
    this.cityGround.visible = !active;
    this.hiddenWorld = this.hiddenWorld || [];
  }
}

import * as THREE from 'three';

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;

export const CAR_TYPES = {
  grotto: { name: 'GROTTO GT', maxSpeed: 47, accel: 17, brake: 26, handling: 1.55, fuel: 100, consumption: 1.15, mass: 1300, color: 0xff2f8e },
  sedan: { name: 'LEONIDA SEDAN', maxSpeed: 38, accel: 12, brake: 22, handling: 1.35, fuel: 90, consumption: 0.9, mass: 1500, color: 0x6d8fa8 },
  muscle: { name: 'VICE MUSCLE', maxSpeed: 46, accel: 16, brake: 20, handling: 1.2, fuel: 95, consumption: 1.35, mass: 1600, color: 0xb03a2e },
  van: { name: 'GELHORN VAN', maxSpeed: 31, accel: 9, brake: 18, handling: 1.0, fuel: 110, consumption: 1.0, mass: 2200, color: 0xb9b2a6 },
  sports: { name: 'VAPID TORERO', maxSpeed: 54, accel: 21, brake: 30, handling: 1.7, fuel: 85, consumption: 1.5, mass: 1200, color: 0xffd166 },
  police: { name: 'POLICE CRUISER', maxSpeed: 50, accel: 19, brake: 28, handling: 1.5, fuel: 120, consumption: 1.4, mass: 1500, color: 0x1b2430 },
  ev: { name: 'VOLT EV', maxSpeed: 43, accel: 18, brake: 26, handling: 1.45, fuel: 100, consumption: 0, mass: 1400, color: 0x9fe8ff, isEV: true },
  taxi: { name: 'BEACH TAXI', maxSpeed: 39, accel: 13, brake: 23, handling: 1.4, fuel: 90, consumption: 1.0, mass: 1450, color: 0xf2c14e },
};

const wheelGeo = new THREE.CylinderGeometry(0.36, 0.36, 0.26, 10);
wheelGeo.rotateZ(Math.PI / 2);

function box(w, h, d, color, opts = {}) {
  return new THREE.Mesh(new THREE.BoxGeometry(w, h, d), new THREE.MeshStandardMaterial({ color, roughness: opts.rough ?? 0.42, metalness: opts.metal ?? 0.5, emissive: opts.emissive ?? 0x000000, emissiveIntensity: opts.ei ?? 0 }));
}

export function buildCarMesh(type, colorOverride) {
  const spec = CAR_TYPES[type] || CAR_TYPES.sedan;
  const color = colorOverride ?? spec.color;
  const g = new THREE.Group();
  const body = new THREE.Group();
  const isVan = type === 'van';
  const isSports = type === 'sports';
  const len = isVan ? 4.9 : isSports ? 4.35 : 4.15;
  const wid = isVan ? 2.1 : 1.92;
  const main = box(wid, 0.52, len, color, { rough: 0.32, metal: 0.75 });
  main.position.y = 0.66; body.add(main);
  const lower = box(wid + 0.03, 0.28, len - 0.2, 0x17171c, { rough: 0.7, metal: 0.3 });
  lower.position.y = 0.38; body.add(lower);
  // hood wedge
  const hood = box(wid - 0.12, 0.22, len * 0.3, color, { rough: 0.32, metal: 0.75 });
  hood.position.set(0, 0.95, len * 0.28); body.add(hood);
  const cabinH = isVan ? 1.5 : isSports ? 0.56 : 0.68;
  const cabin = box(wid - 0.16, cabinH, len * 0.44, 0x1c2630, { rough: 0.12, metal: 0.9 });
  cabin.position.set(0, 0.92 + cabinH / 2, isVan ? 0.25 : -0.15); body.add(cabin);
  const cabinTop = box(wid - 0.2, 0.12, len * 0.4, color, { rough: 0.3, metal: 0.7 });
  cabinTop.position.set(0, 0.92 + cabinH + 0.04, isVan ? 0.25 : -0.15); body.add(cabinTop);
  // bumpers
  const bumperF = box(wid + 0.04, 0.22, 0.24, 0x22222a, { metal: 0.6 });
  bumperF.position.set(0, 0.5, len / 2 + 0.06); body.add(bumperF);
  const bumperR = box(wid + 0.04, 0.22, 0.24, 0x22222a, { metal: 0.6 });
  bumperR.position.set(0, 0.5, -len / 2 - 0.06); body.add(bumperR);
  // lights
  const headMat = new THREE.MeshBasicMaterial({ color: 0xfff2c8, toneMapped: false });
  const tailMat = new THREE.MeshBasicMaterial({ color: 0xff2233, toneMapped: false });
  for (const sx of [-1, 1]) {
    const hl = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.16, 0.06), headMat);
    hl.position.set(sx * (wid / 2 - 0.3), 0.78, len / 2 + 0.11); body.add(hl);
    const tl = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.14, 0.06), tailMat);
    tl.position.set(sx * (wid / 2 - 0.3), 0.78, -len / 2 - 0.1); body.add(tl);
  }
  if (type === 'police') {
    const bar = new THREE.Mesh(new THREE.BoxGeometry(1.1, 0.14, 0.32), new THREE.MeshBasicMaterial({ color: 0xff2233, toneMapped: false }));
    bar.position.set(0, 1.9, -0.05); body.add(bar);
    const bar2 = new THREE.Mesh(new THREE.BoxGeometry(1.1, 0.14, 0.32), new THREE.MeshBasicMaterial({ color: 0x2233ff, toneMapped: false, transparent: true, opacity: 0.6 }));
    bar2.position.set(0, 1.9, -0.05); body.add(bar2);
    g.userData.bar1 = bar; g.userData.bar2 = bar2;
    const stripe = new THREE.Mesh(new THREE.PlaneGeometry(wid - 0.04, 0.5), new THREE.MeshBasicMaterial({ color: 0xe9e9ee }));
    stripe.position.set(0, 0.68, -len / 2 - 0.13); stripe.rotation.y = Math.PI; body.add(stripe);
  }
  if (type === 'taxi') {
    const sign = box(0.6, 0.22, 0.3, 0xffd166, { emissive: 0xffb300, ei: 1.2 });
    sign.position.set(0, 1.78, -0.1); body.add(sign);
  }
  if (isSports) {
    const spoiler = box(wid - 0.2, 0.08, 0.4, 0x17171c, { metal: 0.7 });
    spoiler.position.set(0, 1.2, -len / 2 + 0.24); body.add(spoiler);
    for (const sx of [-0.6, 0.6]) { const sup = box(0.08, 0.24, 0.08, 0x17171c); sup.position.set(sx, 1.08, -len / 2 + 0.24); body.add(sup); }
  }
  // wheels
  const wheels = [];
  const wb = len * 0.31;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const w = new THREE.Mesh(wheelGeo, new THREE.MeshStandardMaterial({ color: 0x121216, roughness: 0.9 }));
    w.position.set(sx * (wid / 2 - 0.03), 0.37, sz * wb); w.castShadow = true;
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 0.28, 8), new THREE.MeshStandardMaterial({ color: 0x9b9ba8, metalness: 0.9, roughness: 0.25 }));
    hub.rotation.z = Math.PI / 2; hub.position.copy(w.position); 
    body.add(w); body.add(hub);
    wheels.push({ w, hub, sx, sz });
  }
  g.add(body);
  // underglow
  if (type === 'grotto' || type === 'ev') {
    const glow = new THREE.Mesh(new THREE.PlaneGeometry(wid + 1.0, len + 0.6), new THREE.MeshBasicMaterial({ color: type === 'ev' ? 0x38e8ff : 0xff2f8e, transparent: true, opacity: 0.28, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false }));
    glow.rotation.x = -Math.PI / 2; glow.position.y = 0.06; g.add(glow); g.userData.underglow = glow;
  }
  g.userData = { ...g.userData, body, wheels, headMat, tailMat, len, wid };
  return g;
}

export class Vehicle {
  constructor(type, scene, opts = {}) {
    this.type = type;
    this.spec = CAR_TYPES[type] || CAR_TYPES.sedan;
    this.scene = scene;
    this.mesh = buildCarMesh(type, opts.color);
    scene.add(this.mesh);
    this.pos = this.mesh.position;
    this.heading = opts.heading ?? 0;
    this.speed = 0;
    this.fuel = opts.fuel ?? this.spec.fuel;
    this.maxFuel = this.spec.fuel;
    this.health = 100;
    this.maxHealth = 100;
    this.locked = !!opts.locked;
    this.personal = !!opts.personal;
    this.isEV = !!this.spec.isEV;
    this.occupied = !!opts.occupied;
    this.police = type === 'police';
    this.driver = opts.driver || null;
    this.ai = opts.ai || null;
    this.seats = 2;
    this.driverSeat = null;
    this.passengerSeat = null;
    this.steerVisual = 0;
    this.wheelSpin = 0;
    this.sirenT = 0;
    this.prevSpeed = 0;
    this.smokeT = 0;
    this.dead = false;
    this.parkedBrake = true;
    this.throttle = 0;
    this.node = opts.node || null;
    this.spawnedByPolice = !!opts.policeSpawn;
    this.aiTimer = 0;
    this.hitCooldown = 0;
    this.braking = false;
    this.turning = 0;
    this.mesh.userData.vehicle = this;
    this.mesh.traverse(o => { o.userData.vehicle = this; });
    if (opts.x !== undefined) this.pos.set(opts.x, 0, opts.z);
    this.mesh.rotation.y = this.heading;
    this.parkedBrake = !opts.ai;
    this.setLights(0);
  }

  setLights(night) {
    const { headMat, tailMat } = this.mesh.userData;
    if (headMat) headMat.color.setHex(this.speed !== 0 || this.driver ? 0xfff2c8 : 0x8a846f);
    if (tailMat) tailMat.color.setHex(this.braking ? 0xff5544 : 0x9c1420);
    if (this.mesh.userData.underglow) this.mesh.userData.underglow.material.opacity = 0.18 + night * 0.3;
  }

  headingVector(out = new THREE.Vector3()) {
    return out.set(Math.sin(this.heading), 0, Math.cos(this.heading));
  }

  forwardPoint(dist, out = new THREE.Vector3()) {
    return out.set(this.pos.x + Math.sin(this.heading) * dist, 0, this.pos.z + Math.cos(this.heading) * dist);
  }

  update(dt, controls, world, time, game) {
    if (this.dead) return;
    const spec = this.spec;
    const throttle = controls?.throttle || 0;
    const brake = controls?.brake || 0;
    const steer = controls?.steer || 0;
    const handbrake = !!controls?.handbrake;
    this.throttle = throttle;
    this.braking = brake > 0;

    if (this.fuel <= 0) this.fuel = 0;
    const canDrive = this.fuel > 0;

    if (canDrive) {
      if (throttle > 0) this.speed += spec.accel * throttle * dt * (this.speed < 0 ? 2.2 : 1);
      if (brake > 0) {
        if (this.speed > 0.4) this.speed -= spec.brake * brake * dt;
        else this.speed -= spec.accel * 0.42 * brake * dt;
      }
      // idle creep down
      if (throttle === 0 && brake === 0) this.speed *= 1 - 0.55 * dt;
      this.fuel = Math.max(0, this.fuel - (Math.abs(throttle) * spec.consumption + 0.05) * dt);
    } else {
      this.speed *= 1 - 1.2 * dt;
    }

    this.speed = clamp(this.speed, -spec.maxSpeed * 0.35, spec.maxSpeed);
    if (handbrake) this.speed *= 1 - 3.2 * dt;

    const speedFactor = clamp(Math.abs(this.speed) / 13, 0, 1.25);
    const direction = this.speed < 0 ? -1 : 1;
    const turn = steer * spec.handling * speedFactor * 0.95 * direction;
    this.heading += turn * dt * (handbrake ? 1.3 : 1);
    this.turning = turn;

    const fwd = this.headingVector(this._fwd || (this._fwd = new THREE.Vector3()));
    this.pos.x += fwd.x * this.speed * dt;
    this.pos.z += fwd.z * this.speed * dt;

    // collision with world, check front + rear
    const r = 1.15;
    const front = this.forwardPoint(1.45, this._p1 || (this._p1 = new THREE.Vector3()));
    const rear = this.forwardPoint(-1.45, this._p2 || (this._p2 = new THREE.Vector3()));
    let hit = false;
    const tp = new THREE.Vector3(front.x, 0, front.z);
    if (world.collideCircle(tp, r)) hit = true;
    this.pos.x += tp.x - front.x; this.pos.z += tp.z - front.z;
    const tp2 = new THREE.Vector3(rear.x, 0, rear.z);
    if (world.collideCircle(tp2, r)) hit = true;
    this.pos.x += tp2.x - rear.x; this.pos.z += tp2.z - rear.z;
    if (hit) {
      const impact = Math.abs(this.speed);
      if (impact > 12) {
        this.damage(impact * 0.7, game);
        if (game?.onCarCrash) game.onCarCrash(this, impact);
      }
      this.speed *= -0.12;
    }

    // collide with other vehicles (simple)
    if (game && game.vehicles) {
      for (const other of game.vehicles) {
        if (other === this || other.dead) continue;
        const dx = other.pos.x - this.pos.x, dz = other.pos.z - this.pos.z;
        const d2 = dx * dx + dz * dz;
        if (d2 < 7.5 && d2 > 0.01) {
          const d = Math.sqrt(d2);
          const push = (2.74 - d) * 0.5;
          this.pos.x -= (dx / d) * push; this.pos.z -= (dz / d) * push;
          other.pos.x += (dx / d) * push; other.pos.z += (dz / d) * push;
          if (Math.abs(this.speed) > 8) {
            this.damage(Math.abs(this.speed) * 0.25, game); other.damage(Math.abs(this.speed) * 0.2, game);
            this.speed *= 0.55;
            if (game.onCarCrash) game.onCarCrash(this, Math.abs(this.speed));
          }
        }
      }
    }

    // visuals
    this.mesh.position.copy(this.pos);
    this.mesh.rotation.y = this.heading;
    this.mesh.rotation.z = lerp(this.mesh.rotation.z, -turn * 0.06 * clamp(Math.abs(this.speed) / 25, 0, 1), 0.1);
    this.wheelSpin += this.speed * dt / 0.36;
    for (const wh of this.mesh.userData.wheels) {
      wh.w.rotation.x = this.wheelSpin;
      if (wh.sz > 0) wh.w.rotation.y = steer * 0.42;
      wh.hub.rotation.x = this.wheelSpin;
    }
    this.setLights(world.nightFactor);
    // siren flash
    if (this.police && this.mesh.userData.bar1) {
      this.sirenT += dt;
      const on = Math.sin(this.sirenT * 8) > 0;
      this.mesh.userData.bar1.material.color.setHex(on ? 0xff2233 : 0x2a0a0e);
      this.mesh.userData.bar2.material.opacity = on ? 0.12 : 0.95;
    }
    // damage smoke
    if (this.health < 35) {
      this.smokeT += dt;
      if (this.smokeT > 1.4) { this.smokeT = 0; game?.spawnSmoke?.(this); }
    }
  }

  damage(amount, game) {
    if (this.dead) return;
    this.health -= amount;
    if (this.health <= 0) {
      this.health = 0;
      this.dead = true;
      if (game) game.explodeVehicle(this);
    }
  }

  refuel(world, amount, game) {
    if (this.isEV) this.fuel = Math.min(this.maxFuel, this.fuel + amount);
    else this.fuel = Math.min(this.maxFuel, this.fuel + amount);
    this.health = Math.min(100, this.health + 25);
    if (game) game.toast(`${this.isEV ? 'CHARGE' : 'FUEL'} ${Math.round(this.fuel)}% · BODY REPAIRED`, 'good');
  }

  enterSeat(who, seat) {
    if (seat === 'driver') this.driverSeat = who;
    else this.passengerSeat = who;
    this.occupied = true;
    this.parkedBrake = false;
  }

  exitSeat(who) {
    if (this.driverSeat === who) this.driverSeat = null;
    if (this.passengerSeat === who) this.passengerSeat = null;
    if (!this.driverSeat && !this.passengerSeat) this.occupied = false;
  }

  seatPosition(seat, out = new THREE.Vector3()) {
    const x = seat === 'driver' ? -0.42 : 0.42;
    const z = -0.1;
    const s = Math.sin(this.heading), c = Math.cos(this.heading);
    out.set(this.pos.x + c * x + s * z, 0.7, this.pos.z - s * x + c * z);
    return out;
  }
}

// ------------------------------------------------------------------ traffic
const ROAD = 80;
export class TrafficSystem {
  constructor(scene, world) {
    this.scene = scene;
    this.world = world;
    this.vehicles = [];
    this.peds = [];
    this.rngSeed = 77;
  }
  rng() { this.rngSeed = (this.rngSeed * 1664525 + 1013904223) >>> 0; return this.rngSeed / 4294967296; }
  range(a, b) { return a + (b - a) * this.rng(); }
  pick(a) { return a[Math.floor(this.rng() * a.length)]; }

  spawnTraffic(game) {
    const road = 80, min = -5, max = 4;
    const types = ['sedan', 'muscle', 'taxi', 'van', 'sports', 'ev'];
    for (let i = 0; i < 16; i++) {
      let gx = Math.floor(this.range(min, max + 1)), gz = Math.floor(this.range(min, max + 1));
      if (Math.abs(gx * road) < 90 && Math.abs(gz * road) < 90) { gx += 2; gz += 1; }
      const dir = this.pick([[1, 0], [-1, 0], [0, 1], [0, -1]]);
      const x = gx * road - dir[0] * 4 * this.range(-1, 1);
      const z = gz * road - dir[1] * 4 * this.range(-1, 1);
      const heading = Math.atan2(dir[0], dir[1]);
      const v = new Vehicle(this.pick(types), this.scene, { x, z, heading, locked: false, ai: true, occupied: true });
      v.traffic = true;
      v.aiDir = dir;
      v.aiNode = { x: gx * road, z: gz * road };
      v.aiTarget = { x: (gx + dir[0]) * road, z: (gz + dir[1]) * road };
      v.cruise = this.range(9, 15);
      this.vehicles.push(v);
      game.vehicles.push(v);
      game.trafficCars.push(v);
    }
    // parked, locked cars
    for (let i = 0; i < 8; i++) {
      const gx = Math.floor(this.range(-5, 5)), gz = Math.floor(this.range(-5, 5));
      const axis = this.rng() > 0.5;
      const x = axis ? gx * road + this.range(-4, 4) : gx * road + this.range(20, 55);
      const z = axis ? gz * road + this.range(20, 55) : gz * road + this.range(-4, 4);
      const v = new Vehicle(this.pick(types), this.scene, { x, z, heading: axis ? Math.PI / 2 : 0, locked: this.rng() > 0.25, occupied: false });
      v.parked = true;
      v.parkedBrake = true;
      this.vehicles.push(v); game.vehicles.push(v); game.parkedCars.push(v);
    }
  }

  spawnPeds(game) {
    const clothes = [0xd88a6a, 0x7f9fbf, 0xb0a0d0, 0xe0c090, 0x9f7f6f, 0x6aa08a, 0xd0d0d0];
    for (let i = 0; i < 26; i++) {
      const gx = Math.floor(this.range(-5, 5)), gz = Math.floor(this.range(-5, 5));
      const side = this.rng() > 0.5 ? 1 : -1;
      const x = gx * ROAD + side * 31.5 + this.range(-1.5, 1.5);
      const z = gz * ROAD + this.range(-30, 30);
      const p = makePed(clothes[Math.floor(this.rng() * clothes.length)], this.range(0.9, 1.08));
      p.isPed = true; p.hp = 30; p.maxHp = 30; p.dead = false;
      p.group.position.set(x, 0.27, z);
      p.walkDir = this.range(0, Math.PI * 2);
      p.walkT = 0; p.speed = this.range(0.7, 1.4);
      p.home = { x, z };
      this.scene.add(p.group);
      game.peds.push(p);
      // a couple of vehicles for flavor
    }
  }

  update(dt, game, time) {
    for (const v of this.vehicles) {
      if (v.dead) continue;
      if (v.traffic) this.updateTrafficCar(v, dt, game);
      else if (v.parked || (!v.driverSeat && !v.personal)) {
        v.update(dt, null, this.world, time, game);
      }
    }
    for (const p of game.peds) {
      if (p.dead || p.isPlayer) continue;
      p.walkT += dt;
      const target = p.flee ? game.player.pos : null;
      if (!p.flee) {
        p.group.position.x += Math.sin(p.walkDir) * p.speed * dt;
        p.group.position.z += Math.cos(p.walkDir) * p.speed * dt;
        const dHome = Math.hypot(p.group.position.x - p.home.x, p.group.position.z - p.home.z);
        if (dHome > 26) p.walkDir += Math.PI;
        const r = this.world;
        if (r.isInsideBuilding(p.group.position.x, p.group.position.z, 0.6)) p.walkDir += Math.PI * 0.7;
        if (Math.hypot(p.group.position.x, p.group.position.z) > 640) p.walkDir += Math.PI;
        p.group.rotation.y = p.walkDir;
      } else if (target) {
        const dx = p.group.position.x - target.x, dz = p.group.position.z - target.z;
        const d = Math.hypot(dx, dz) || 1;
        if (d < 22) { p.group.position.x += (dx / d) * 3.4 * dt; p.group.position.z += (dz / d) * 3.4 * dt; p.group.rotation.y = Math.atan2(-dx, -dz); }
      }
      const w = p.group.userData.walker;
      if (w) {
        const sw = Math.sin(p.walkT * (p.flee ? 12 : 7)) * 0.55 * (p.flee ? 1.5 : 1);
        w.legL.rotation.x = sw; w.legR.rotation.x = -sw;
        w.armL.rotation.x = -sw * 0.8; w.armR.rotation.x = sw * 0.8;
      }
      p.group.position.y = 0.27;
    }
  }

  updateTrafficCar(v, dt, game) {
    const target = v.aiTarget;
    const dx = target.x - v.pos.x, dz = target.z - v.pos.z;
    const dist = Math.hypot(dx, dz);
    if (dist < 9) {
      // choose next grid node, avoid U-turn
      const gx = Math.round(target.x / ROAD), gz = Math.round(target.z / ROAD);
      const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]].filter(d => !(d[0] === -v.aiDir[0] && d[1] === -v.aiDir[1]));
      const d = this.pick(dirs);
      v.aiDir = d;
      v.aiTarget = { x: (gx + d[0]) * ROAD, z: (gz + d[1]) * ROAD };
      if (Math.abs(v.aiTarget.x) > 380 || Math.abs(v.aiTarget.z) > 380) v.aiTarget = { x: 0, z: 0 };
    }
    const desired = Math.atan2(dx, dz);
    let diff = ((desired - v.heading + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
    const steer = clamp(diff * 1.8, -1, 1);
    // slow near player / obstacles
    let obstacle = false;
    for (const o of game.vehicles) {
      if (o === v || o.dead) continue;
      const ox = o.pos.x - v.pos.x, oz = o.pos.z - v.pos.z;
      const d = Math.hypot(ox, oz);
      if (d < 9) {
        const fwd = Math.sin(v.heading) * ox + Math.cos(v.heading) * oz;
        if (fwd > 2) { obstacle = true; break; }
      }
    }
    const wanted = obstacle ? 0 : (Math.abs(diff) > 0.8 ? 4 : v.cruise || 11);
    const throttle = v.speed < wanted ? 0.85 : 0;
    const brake = v.speed > wanted + 2 ? 1 : 0;
    v.update(dt, { throttle, brake, steer, handbrake: false }, this.world, game.time, game);
    if (v.health <= 0 && !v.dead) { v.dead = true; game.explodeVehicle(v); }
    // simple ped collision
  }
}

export function makePed(shirtColor, scale = 1) {
  const g = new THREE.Group();
  const skin = [0xc98f6a, 0x8a5a3d, 0xe0b090, 0x6f4630][Math.floor(Math.random() * 4)];
  const pants = [0x2a3040, 0x40352a, 0x1f242c, 0x5a4a3a][Math.floor(Math.random() * 4)];
  const mat = (c) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.9 });
  const torso = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.78, 0.34), mat(shirtColor));
  torso.position.y = 1.18; g.add(torso);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.22, 10, 8), mat(skin));
  head.position.y = 1.75; g.add(head);
  const hair = new THREE.Mesh(new THREE.SphereGeometry(0.225, 8, 6, 0, Math.PI * 2, 0, Math.PI * 0.55), mat(0x241a14));
  hair.position.y = 1.78; g.add(hair);
  const legL = new THREE.Group(), legR = new THREE.Group();
  for (const [leg, sx] of [[legL, -0.17], [legR, 0.17]]) {
    const l = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.78, 0.24), mat(pants));
    l.position.y = -0.34; leg.add(l); leg.position.set(sx, 0.78, 0); g.add(leg);
  }
  const armL = new THREE.Group(), armR = new THREE.Group();
  for (const [arm, sx] of [[armL, -0.42], [armR, 0.42]]) {
    const a = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.64, 0.19), mat(shirtColor));
    a.position.y = -0.28; arm.add(a); arm.position.set(sx, 1.5, 0); g.add(arm);
  }
  g.scale.setScalar(scale);
  g.traverse(o => { if (o.isMesh) { o.castShadow = true; } });
  g.userData.walker = { legL, legR, armL, armR };
  return { group: g, torso, head, hair, legL, legR, armL, armR, scale };
}

import * as THREE from 'three';

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;

export const WEAPONS = [
  { id: 'pistol', name: 'PISTOL', damage: 32, head: 3.2, mag: 12, reserve: 96, rate: 0.28, spread: 0.008, recoil: 0.012, pellets: 1, weight: 1.0, range: 140, sound: 'pistol' },
  { id: 'smg', name: 'SMG', damage: 15, head: 2.4, mag: 30, reserve: 150, rate: 0.085, spread: 0.022, recoil: 0.007, pellets: 1, weight: 0.9, range: 110, sound: 'smg' },
  { id: 'shotgun', name: 'SHOTGUN', damage: 14, head: 2.0, mag: 6, reserve: 36, rate: 0.82, spread: 0.062, recoil: 0.045, pellets: 8, weight: 1.6, range: 55, sound: 'shotgun' },
];

function mat(color, rough = 0.9, metal = 0.02) {
  return new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: metal });
}

export function buildHuman(kind) {
  const isLucia = kind === 'lucia';
  const g = new THREE.Group();
  const skin = mat(isLucia ? 0xb97a54 : 0xc98f6a, 0.85);
  const shirt = mat(isLucia ? 0x201f26 : 0xe8e2d6, 0.9);
  const jacket = mat(isLucia ? 0x6f2338 : 0x2e3b4a, 0.85);
  const pants = mat(isLucia ? 0x2b2f3c : 0x4b5866, 0.95);
  const hairMat = mat(isLucia ? 0x1b1310 : 0x2a211a, 0.95);
  const shoe = mat(0x17161a, 0.8);

  const root = new THREE.Group();
  const body = new THREE.Group(); root.add(body);
  // pelvis
  const pelvis = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.3, 0.32), pants);
  pelvis.position.y = 1.0; body.add(pelvis);
  // torso
  const torso = new THREE.Mesh(new THREE.BoxGeometry(0.64, 0.72, 0.36), isLucia ? shirt : jacket);
  torso.position.y = 1.46; body.add(torso);
  if (!isLucia) {
    const inner = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.64, 0.38), mat(0xd8d2c4));
    inner.position.y = 1.48; body.add(inner);
    const collar = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.12, 0.4), mat(0x1c242e));
    collar.position.y = 1.8; body.add(collar);
  } else {
    const belt = new THREE.Mesh(new THREE.BoxGeometry(0.58, 0.09, 0.36), mat(0x0d0d10));
    belt.position.y = 1.12; body.add(belt);
  }
  // neck/head
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.12, 0.16, 8), skin);
  neck.position.y = 1.86; body.add(neck);
  const headGroup = new THREE.Group(); headGroup.position.y = 2.0; body.add(headGroup);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.225, 14, 12), skin);
  head.scale.set(0.92, 1.06, 0.95); headGroup.add(head);
  const nose = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.09, 0.08), skin);
  nose.position.set(0, -0.02, 0.21); headGroup.add(nose);
  // eyes
  for (const sx of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.026, 6, 5), mat(0x14100e, 0.4));
    eye.position.set(sx * 0.08, 0.04, 0.2); headGroup.add(eye);
  }
  // hair
  let hairGroup = new THREE.Group();
  if (isLucia) {
    const cap = new THREE.Mesh(new THREE.SphereGeometry(0.248, 12, 10, 0, Math.PI * 2, 0, Math.PI * 0.62), hairMat);
    cap.position.y = 0.03; cap.scale.set(1, 1.08, 1); headGroup.add(cap);
    // long strands
    for (let i = 0; i < 7; i++) {
      const w = 0.1 + Math.random() * 0.05;
      const len = 0.55 + Math.random() * 0.28;
      const strand = new THREE.Mesh(new THREE.BoxGeometry(w, len, 0.07), hairMat);
      strand.position.set(-0.18 + i * 0.06, -len / 2 - 0.1, -0.15 - (i % 2) * 0.04);
      strand.rotation.z = (i - 3) * 0.06;
      hairGroup.add(strand);
    }
    const fringe = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.16, 0.1), hairMat);
    fringe.position.set(0, 0.13, 0.17); fringe.rotation.x = 0.2; headGroup.add(fringe);
    headGroup.add(hairGroup);
  } else {
    const cap = new THREE.Mesh(new THREE.SphereGeometry(0.238, 10, 8, 0, Math.PI * 2, 0, Math.PI * 0.52), hairMat);
    cap.position.y = 0.035; headGroup.add(cap);
    const beard = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.1, 0.08), hairMat);
    beard.position.set(0, -0.14, 0.17); headGroup.add(beard);
  }
  // arms
  const armL = new THREE.Group(), armR = new THREE.Group();
  armL.position.set(-0.4, 1.72, 0); armR.position.set(0.4, 1.72, 0);
  for (const [arm, mirror] of [[armL, -1], [armR, 1]]) {
    const upper = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.46, 0.2), isLucia && mirror < 0 ? jacket : shirt);
    upper.position.y = -0.22; arm.add(upper);
    const lower = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.4, 0.17), isLucia ? skin : jacket);
    lower.position.y = -0.6; arm.add(lower);
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.085, 7, 6), skin);
    hand.position.y = -0.82; arm.add(hand);
    body.add(arm);
  }
  // legs
  const legL = new THREE.Group(), legR = new THREE.Group();
  legL.position.set(-0.17, 0.9, 0); legR.position.set(0.17, 0.9, 0);
  for (const [leg, mirror] of [[legL, -1], [legR, 1]]) {
    const thigh = new THREE.Mesh(new THREE.BoxGeometry(0.23, 0.46, 0.26), pants);
    thigh.position.y = -0.22; leg.add(thigh);
    const shin = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.44, 0.22), pants);
    shin.position.y = -0.65; leg.add(shin);
    const foot = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.12, 0.36), shoe);
    foot.position.set(0, -0.9, 0.06); leg.add(foot);
    body.add(leg);
  }
  // gun
  const gun = new THREE.Group();
  const gm = new THREE.MeshStandardMaterial({ color: 0x23242a, roughness: 0.45, metalness: 0.75 });
  const barrel = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.1, 0.42), gm); barrel.position.z = 0.2; gun.add(barrel);
  const grip = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.2, 0.1), gm); grip.position.set(0, -0.13, 0.03); grip.rotation.x = -0.2; gun.add(grip);
  if (kind === 'shotgun') { barrel.scale.z = 1.6; barrel.position.z = 0.36; }
  gun.position.set(0, -0.82, 0.12); gun.visible = false; armR.add(gun);

  root.traverse(o => { if (o.isMesh) { o.castShadow = true; } });
  g.add(root);
  return {
    kind, group: g, root, body, headGroup, hairGroup, armL, armR, legL, legR, gun,
    parts: { head, torso, pelvis, armL, armR, legL, legR },
  };
}

export class Character {
  constructor(kind, scene, opts = {}) {
    this.kind = kind;
    this.name = kind === 'jason' ? 'JASON' : 'LUCIA';
    const b = buildHuman(kind);
    this.model = b;
    this.group = b.group;
    this.group.position.set(opts.x ?? 0, 0.27, opts.z ?? 0);
    this.pos = this.group.position;
    this.vel = new THREE.Vector3();
    this.heading = opts.heading ?? 0;
    this.moveSpeed = 4.7;
    this.sprintSpeed = 8.4;
    this.speed = 0;
    this.vy = 0;
    this.onGround = true;
    this.hp = 100;
    this.maxHp = 100;
    this.armor = 0;
    this.focus = 100;
    this.maxFocus = 100;
    this.focusActive = false;
    this.aim = false;
    this.sprinting = false;
    this.inVehicle = null;
    this.seat = null;
    this.dead = false;
    this.phase = Math.random() * 6;
    this.weapons = WEAPONS.map(w => ({ ...w, magAmmo: w.mag, reserveAmmo: w.reserve }));
    this.weapon = 0;
    this.fireCooldown = 0;
    this.reloading = false;
    this.reloadT = 0;
    this.recoil = 0;
    this.aimSway = 0;
    this.lastShot = 0;
    this.beam = null;
    this.setVisible = true;
    this.hairPhase = Math.random() * 7;
    scene.add(this.group);
    this.model.gun.visible = true;
    this.btn = { x: 0, z: 0 };
  }

  get weaponDef() { return this.weapons[this.weapon]; }

  lookAtPoint(x, z) { this.heading = Math.atan2(x - this.pos.x, z - this.pos.z); }

  update(dt, input, cameraYaw, world, game) {
    if (this.dead) return;
    this.fireCooldown = Math.max(0, this.fireCooldown - dt);
    this.recoil = Math.max(0, this.recoil - dt * 5.5);
    this.aimSway += dt * (0.8 + this.weaponDef.weight * 0.7);

    if (this.reloading) {
      this.reloadT -= dt;
      if (this.reloadT <= 0) {
        const w = this.weaponDef;
        const need = w.mag - w.magAmmo;
        const take = Math.min(need, w.reserveAmmo);
        w.magAmmo += take; w.reserveAmmo -= take;
        this.reloading = false;
        game?.updateHud?.();
      }
    }

    // focus
    if (this.inVehicle == null) {
      if (input.focus && !this.focusActive && this.focus > 2) {
        this.focusActive = true;
        game?.audio?.pickup?.(true);
      }
      if (!input.focus || this.focus <= 0.5) this.focusActive = false;
      if (this.focusActive) this.focus = Math.max(0, this.focus - dt * 12);
      else this.focus = Math.min(this.maxFocus, this.focus + dt * 4.5);
    } else {
      this.focusActive = false;
      this.focus = Math.min(this.maxFocus, this.focus + dt * 2);
    }

    // movement relative to camera
    let mx = 0, mz = 0;
    if (!this.inVehicle && !game.uiLocked) {
      if (input.forward) mz += 1;
      if (input.back) mz -= 1;
      if (input.left) mx -= 1;
      if (input.right) mx += 1;
    }
    const len = Math.hypot(mx, mz);
    let moving = false;
    if (len > 0.01) {
      mx /= len; mz /= len;
      const sin = Math.sin(cameraYaw), cos = Math.cos(cameraYaw);
      const wx = mx * cos + mz * sin;
      const wz = -mx * sin + mz * cos;
      const target = this.aim ? 3.1 : this.sprinting ? this.sprintSpeed : this.moveSpeed;
      const heavy = this.weaponDef.weight > 1.3 ? 0.86 : 1;
      const sp = target * heavy;
      this.pos.x += wx * sp * dt;
      this.pos.z += wz * sp * dt;
      this.heading = Math.atan2(wx, wz);
      this.speed = sp;
      moving = true;
    } else this.speed = 0;

    if (this.inVehicle == null) {
      world.collideCircle(this.pos, 0.48);
      // jump
      if (input.jump && this.onGround) { this.vy = 6.4; this.onGround = false; }
      this.vy -= 19 * dt;
      this.pos.y += this.vy * dt;
      if (this.pos.y <= 0.27) { this.pos.y = 0.27; this.vy = 0; this.onGround = true; }
      // clamp world
      if (Math.hypot(this.pos.x, this.pos.z) > 650) { this.pos.x *= 0.99; this.pos.z *= 0.99; }
    }

    this.group.rotation.y = this.heading;
    this.animate(dt, moving, world);
  }

  animate(dt, moving, world) {
    const b = this.model;
    const aim = this.aim && !this.inVehicle;
    if (moving) this.phase += dt * (this.sprinting ? 12 : 8);
    else this.phase += dt * 1.6;
    const sw = moving ? Math.sin(this.phase) * (this.sprinting ? 0.95 : 0.62) : 0;
    b.legL.rotation.x = sw;
    b.legR.rotation.x = -sw;
    if (aim) {
      b.armR.rotation.x = lerp(b.armR.rotation.x, -1.55 - this.recoil * 0.8, 0.35);
      b.armL.rotation.x = lerp(b.armL.rotation.x, -1.2, 0.3);
      b.armL.rotation.y = 0.35; b.armR.rotation.y = -0.05;
    } else {
      b.armL.rotation.x = lerp(b.armL.rotation.x, -sw * 0.8, 0.4);
      b.armR.rotation.x = lerp(b.armR.rotation.x, sw * 0.8, 0.4);
      b.armL.rotation.y = 0; b.armR.rotation.y = 0;
    }
    b.body.position.y = moving ? Math.abs(Math.sin(this.phase)) * 0.045 : Math.sin(this.phase) * 0.012;
    b.headGroup.rotation.x = aim ? -0.08 : Math.sin(this.phase * 0.5) * 0.02;
    // hair wind
    if (this.kind === 'lucia' && b.hairGroup) {
      const t = performance.now() * 0.001;
      const wind = world?.weather?.wind || 0.6;
      b.hairGroup.children.forEach((c, i) => {
        c.rotation.x = Math.sin(t * 2.2 + i * 0.4) * 0.08 * wind + (this.sprinting ? -0.2 : 0);
        c.rotation.z = (i - 3) * 0.06 + Math.sin(t * 1.7 + i) * 0.03 * wind;
      });
    }
    // muzzle/recoil arm kick
    if (this.recoil > 0.001 && !aim) b.armR.rotation.x -= this.recoil * 0.5;
  }

  shoot(game, spreadMult = 1) {
    const w = this.weaponDef;
    if (this.fireCooldown > 0 || this.reloading) return false;
    if (w.magAmmo <= 0) { this.reload(game); return false; }
    w.magAmmo--;
    this.fireCooldown = w.rate;
    this.recoil = Math.min(1, this.recoil + w.recoil * 20);
    this.lastShot = performance.now();
    game.audio?.shot(w.sound);
    game.fireBullet(this, w, spreadMult);
    game.updateHud();
    if (w.magAmmo === 0) this.reload(game);
    return true;
  }

  reload(game) {
    const w = this.weaponDef;
    if (this.reloading || w.magAmmo >= w.mag || w.reserveAmmo <= 0) return;
    this.reloading = true;
    this.reloadT = 1.35;
    game.audio?.reload();
    game.toast(`RELOADING ${w.name}`, '');
  }

  switchWeapon(i, game) {
    if (i === this.weapon) return;
    this.weapon = i; this.reloading = false; this.fireCooldown = 0.2;
    game.audio?.tick();
    game.updateHud();
  }

  damage(amount, game, source) {
    if (this.dead) return;
    let dmg = amount;
    if (this.armor > 0) { const abs = Math.min(this.armor, dmg * 0.7); this.armor -= abs; dmg -= abs; }
    this.hp -= dmg;
    game?.onPlayerDamaged?.(this, dmg, source);
    if (this.hp <= 0) { this.hp = 0; this.dead = true; game?.onPlayerDeath?.(this); }
  }

  heal(n) { this.hp = Math.min(this.maxHp, this.hp + n); }

  setWeaponModel() {
    const w = this.weaponDef;
    this.model.gun.visible = true;
    this.model.gun.scale.set(1, 1, w.id === 'shotgun' ? 1.5 : w.id === 'smg' ? 1.15 : 1);
  }
}

// Simple enemy class used for cops and gang members
export class Enemy {
  constructor(scene, x, z, kind = 'gang', game) {
    this.kind = kind;
    this.scene = scene;
    this.group = new THREE.Group();
    this.hp = kind === 'cop' ? 70 : 55;
    this.maxHp = this.hp;
    this.dead = false;
    this.pos = this.group.position;
    this.pos.set(x, 0.27, z);
    this.heading = 0;
    this.phase = Math.random() * 5;
    this.fireT = 1 + Math.random() * 2;
    this.state = 'idle';
    this.speed = kind === 'cop' ? 4.1 : 3.4;
    this.game = game;
    this.aggro = false;
    this.weak = null;
    this.corpseT = 0;
    this.walkT = 0;
    this.hitFlash = 0;
    const shirt = kind === 'cop' ? 0x24304f : [0x8f2f3f, 0x2f5f3f, 0x3a3a4a, 0x6f4f2f][Math.floor(Math.random() * 4)];
    const pants = kind === 'cop' ? 0x1c2333 : 0x2b2b34;
    const skin = [0xc98f6a, 0x8a5a3d, 0xe0b090, 0x6f4630][Math.floor(Math.random() * 4)];
    const mk = (c) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.9 });
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.64, 0.78, 0.36), mk(shirt)); torso.position.y = 1.28; this.group.add(torso);
    if (kind === 'cop') {
      const vest = new THREE.Mesh(new THREE.BoxGeometry(0.68, 0.5, 0.4), mk(0x12161f)); vest.position.y = 1.3; this.group.add(vest);
      const badge = new THREE.Mesh(new THREE.PlaneGeometry(0.1, 0.08), new THREE.MeshBasicMaterial({ color: 0xffd166 })); badge.position.set(-0.15, 1.42, 0.2); this.group.add(badge);
    }
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.23, 10, 8), mk(skin)); head.position.y = 1.87; this.group.add(head); this.head = head;
    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.235, 8, 6, 0, Math.PI * 2, 0, Math.PI * 0.5), mk(kind === 'cop' ? 0x1b2538 : 0x201812)); hair.position.y = 1.9; this.group.add(hair);
    if (kind === 'cop') {
      const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.27, 0.16, 10), mk(0x1a2436)); cap.position.y = 2.05; this.group.add(cap);
      const brim = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.04, 0.2), mk(0x111826)); brim.position.set(0, 1.99, 0.2); this.group.add(brim);
    }
    // weak point: neon head halo only visible in focus
    this.weak = new THREE.Mesh(new THREE.SphereGeometry(0.34, 10, 8), new THREE.MeshBasicMaterial({ color: 0xffd166, transparent: true, opacity: 0, wireframe: true, depthWrite: false }));
    this.weak.position.y = 1.87; this.group.add(this.weak);
    this.weak2 = new THREE.Mesh(new THREE.SphereGeometry(0.46, 8, 6), new THREE.MeshBasicMaterial({ color: 0xff2f8e, transparent: true, opacity: 0, wireframe: true, depthWrite: false }));
    this.weak2.position.y = 1.25; this.group.add(this.weak2);
    const legL = new THREE.Group(), legR = new THREE.Group();
    for (const [leg, sx] of [[legL, -0.17], [legR, 0.17]]) {
      const l = new THREE.Mesh(new THREE.BoxGeometry(0.23, 0.82, 0.26), mk(pants)); l.position.y = -0.36; leg.add(l); leg.position.set(sx, 0.82, 0); this.group.add(leg);
    }
    const armL = new THREE.Group(), armR = new THREE.Group();
    for (const [arm, sx] of [[armL, -0.42], [armR, 0.42]]) {
      const a = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.68, 0.2), mk(shirt)); a.position.y = -0.3; arm.add(a); arm.position.set(sx, 1.6, 0); this.group.add(arm);
    }
    // gun
    const gun = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.12, 0.5), new THREE.MeshStandardMaterial({ color: 0x1b1b20, metalness: 0.8, roughness: 0.4 }));
    gun.position.set(0, -0.65, 0.22); armR.add(gun);
    this.armL = armL; this.armR = armR; this.legL = legL; this.legR = legR;
    this.group.traverse(o => { if (o.isMesh) o.castShadow = true; });
    scene.add(this.group);
  }

  update(dt, game) {
    if (this.dead) {
      this.corpseT += dt;
      return;
    }
    this.fireT -= dt;
    this.hitFlash = Math.max(0, this.hitFlash - dt * 4);
    const player = game.activeChar;
    const dx = player.pos.x - this.pos.x, dz = player.pos.z - this.pos.z;
    const dist = Math.hypot(dx, dz);
    this.weak.material.opacity = game.focus ? 0.85 : 0;
    this.weak2.material.opacity = game.focus ? 0.55 : 0;
    const headTarget = this.head;
    if (game.focus) { this.weak.material.opacity = 0.6 + Math.sin(game.time * 6) * 0.25; }
    if (this.hitFlash > 0) { this.head.material.emissive = new THREE.Color(0xff5566); this.head.material.emissiveIntensity = 0.6; }
    else { this.head.material.emissiveIntensity = 0; }

    if (this.aggro && dist > 2.2 && dist < 80) {
      const nx = dx / (dist || 1), nz = dz / (dist || 1);
      if (dist > 9) {
        this.pos.x += nx * this.speed * dt; this.pos.z += nz * this.speed * dt;
      } else if (dist < 6) {
        this.pos.x -= nx * this.speed * 0.5 * dt; this.pos.z -= nz * this.speed * 0.5 * dt;
      }
      // strafe
      this.pos.x += -nz * Math.sin(game.time * 0.8 + this.phase) * 1.2 * dt;
      this.pos.z += nx * Math.sin(game.time * 0.8 + this.phase) * 1.2 * dt;
      game.world.collideCircle(this.pos, 0.45);
      this.heading = Math.atan2(dx, dz);
      this.walkT += dt * 8;
      this.legL.rotation.x = Math.sin(this.walkT) * 0.6;
      this.legR.rotation.x = -Math.sin(this.walkT) * 0.6;
      this.armR.rotation.x = -1.45;
      this.armL.rotation.x = -1.1;
      // shoot
      if (this.fireT <= 0 && dist < 48) {
        this.fireT = (this.kind === 'cop' ? 1.1 : 1.35) + Math.random() * 0.9;
        game.enemyShoot(this, dist);
      }
    } else {
      this.walkT += dt * 2.2;
      this.legL.rotation.x = Math.sin(this.walkT) * 0.1;
      this.legR.rotation.x = -Math.sin(this.walkT) * 0.1;
      this.armR.rotation.x = 0; this.armL.rotation.x = 0;
    }
    this.group.rotation.y = this.heading;
    this.group.position.y = 0.27;
  }

  damage(amount, game, fromHead = false) {
    if (this.dead) return;
    this.hp -= amount;
    this.hitFlash = 1;
    this.aggro = true;
    game?.audio?.hit?.();
    if (this.hp <= 0) {
      this.dead = true;
      this.aggro = false;
      this.group.rotation.x = -Math.PI / 2;
      this.group.position.y = 0.35;
      this.weak.material.opacity = 0; this.weak2.material.opacity = 0;
      game?.onEnemyKilled?.(this, fromHead);
    }
  }
}

import { POI } from './world.js';

// Mission chain for the Jason & Lucia story. Each step has a waypoint, a check and
// optional enter logic. The MissionSystem drives objective HUD + payout.
export class MissionSystem {
  constructor(game) {
    this.g = game;
    this.missions = buildMissions();
    this.index = -1;
    this.step = 0;
    this.stepTime = 0;
    this.active = false;
    this.pending = -1;
    this.pendingT = 0;
    this.marker = null;
    this.finished = false;
  }

  start(index) {
    if (index >= this.missions.length) { this.finished = true; return; }
    this.index = index; this.step = 0; this.stepTime = 0; this.active = true;
    const m = this.missions[index];
    this.g.toast(`MISSION · ${m.title}`, 'money');
    this.g.clearMissionFlags?.();
    this.enterStep();
    this.g.say(m.who || 'JASON', m.intro || m.title, 4.2);
  }

  get mission() { return this.missions[this.index]; }
  get current() { return this.mission?.steps[this.step]; }

  enterStep() {
    const s = this.current;
    if (!s) return;
    this.stepTime = 0;
    if (s.enter) s.enter(this.g);
    if (s.text) this.g.toast(s.text, '');
  }

  update(dt) {
    if (this.pending >= 0) {
      this.pendingT -= dt;
      if (this.pendingT <= 0) {
        const idx = this.pending; this.pending = -1;
        this.start(idx);
      }
      return;
    }
    if (!this.active) return;
    this.stepTime += dt;
    const s = this.current;
    if (!s) return;
    const wp = s.waypoint ? s.waypoint(this.g) : null;
    this.marker = wp;
    let dist = 0;
    if (wp) {
      const c = this.g.activeChar;
      dist = Math.hypot(c.pos.x - wp.x, c.pos.z - wp.z);
    }
    this.g.updateMissionHud(this.mission, s, dist);
    if (s.check && s.check(this.g, this.stepTime)) this.advance();
  }

  advance() {
    const m = this.mission;
    this.step++;
    if (this.step >= m.steps.length) {
      this.complete();
      return;
    }
    this.g.audio?.pickup?.(true);
    this.enterStep();
  }

  complete() {
    const m = this.mission;
    this.active = false;
    this.marker = null;
    this.g.onMissionComplete(m);
    if (this.index + 1 < this.missions.length) {
      this.pending = this.index + 1;
      this.pendingT = 9;
      this.g.updateMissionHud(null, null, 0);
    } else {
      this.finished = true;
      this.g.freeRoam = true;
      this.g.updateMissionHud(null, null, 0);
    }
  }

  failReset() {
    if (!this.active) return;
    this.step = 0; this.stepTime = 0;
    this.g.clearMissionFlags?.();
    this.enterStep();
    this.g.toast('MISSION RESET · GET BACK TO IT', 'bad');
  }

  cancel() {
    this.active = false; this.marker = null;
    this.g.updateMissionHud(null, null, 0);
  }
}

function buildMissions() {
  return [
    {
      id: 'm1', title: 'FIRST SHIFT', who: 'LUCIA',
      intro: 'Nice ride. Shame it is running on fumes. Gas station first, then we talk business.',
      steps: [
        {
          text: 'Get in the Grotto GT', waypoint: g => g.personalCar ? { x: g.personalCar.pos.x, z: g.personalCar.pos.z } : null,
          check: g => g.activeChar.inVehicle === g.personalCar,
        },
        {
          text: 'Fuel up at Gas & Go — pull in and press E', waypoint: () => POI.gas.door,
