import { AudioEngine } from './audio.js';
import { MissionSystem } from './missions.js';

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;
const angleLerp = (a, b, t) => {
