    if (Math.abs(d) < 1e-8) {
      if (o < mn || o > mx) return null;
    } else {
      let t1 = (mn - o) / d, t2 = (mx - o) / d;
      if (t1 > t2) { const t = t1; t1 = t2; t2 = t; }
      tmin = Math.max(tmin, t1); tmax = Math.min(tmax, t2);
      if (tmin > tmax) return null;
    }
  }
  return tmin > 0 ? tmin : null;
}

class Game {
  constructor() {
    this.state = 'boot';
    this.started = false;
    this.uiLocked = false;
    this.time = 0;
    this.clock = new THREE.Clock();
    this.timeScale = 1;
    this.cash = 420;
    this.bank = 1250;
    this.bags = [1250, 1680];
    this.policeKills = 0;
    this.flags = {};
    this.freeRoam = false;
    this.inInterior = false;
    this.heat = 0;
    this.suspicion = 0;
    this.visualContact = false;
    this.escapeTimer = 0;
    this.dispatch = { t: 0, pending: 0, severity: 0 };
    this.profile = { violence: 0, notoriety: 0, witnesses: 0 };
    this.vehicles = [];
    this.policeCars = [];
    this.police = [];
    this.enemies = [];
    this.peds = [];
    this.parkedCars = [];
    this.trafficCars = [];
    this.pickups = [];
    this.corpses = [];
    this.effects = [];
    this.toasts = [];
    this.subQueue = [];
    this.subCurrent = null;
    this.subT = 0;
    this.promptCache = '';
    this.heatCooldown = 0;
    this.dispatchSpawnT = 0;
    this.copSpawnT = 0;
    this.arrestT = 0;
    this.deathT = 0;
    this.shake = 0;
    this.recoilKick = 0;
    this.spread = 0;
    this.mouseDown = false;
    this.touchFire = false;
    this.focus = false;
    this.lastDamage = 0;
    this.radioT = 0;
    this.camYaw = Math.PI / 2;
    this.camPitch = -0.16;
    this.camDist = 5;
    this.camLook = new THREE.Vector3();
    this.recentMouse = 0;
    this.isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    this.frameTimes = [];
    this.lowPerf = false;
    this.stats = { kills: 0, arrests: 0, stolen: 0, missions: 0, distance: 0 };
    this.duffelVisible = false;
    this.hold = null;
    this.input = { forward: false, back: false, left: false, right: false, jump: false, sprint: false, aim: false, focus: false, interact: false, interactPressed: false, firePressed: false };
    this._tmp = new THREE.Vector3();
    this._tmp2 = new THREE.Vector3();
    this._tmp3 = new THREE.Vector3();
    this._dir = new THREE.Vector3();
    this.init();
  }

  init() {
    const app = document.getElementById('app');
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance', stencil: false });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, this.isTouch ? 1.25 : 1.6));
