    this.updatePhone();
    this.toast(kind === 'busted' ? 'RELEASED · NO CASH, NO LOOT' : 'PATCHED UP AT MERCY HOSPITAL', 'bad');
    this.say('LUCIA', 'You okay? We lost the cash. Bank is still clean. Get back to it.', 4.2);
    this.canvas.requestPointerLock?.();
