    this.camera.position.y = Math.max(0.8, this.camera.position.y - dt * 0.4);
    this.world.update(dt, this.camera, false, this);
    this.updateEffects(dt);
    this.updateDialogue(dt);
    this.updateHudTick(dt);
    this.updateAudio(dt);
