import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
const errors = []
page.on('pageerror', e => errors.push(e.message))
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`) })

await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 60000 })
await page.waitForTimeout(2200)
await page.click('#btnPlay')
await page.waitForTimeout(1800)

// Walk up to the personal car without waiting for slow software-rendered travel.
await page.evaluate(() => {
  const g = window.game
  g.activeChar.pos.set(g.personalCar.pos.x - 2, 0.27, g.personalCar.pos.z)
  g.activeChar.group.position.copy(g.activeChar.pos)
})
await page.waitForTimeout(500)
await page.keyboard.press('KeyF')
await page.waitForTimeout(1200)

const afterEnter = await page.evaluate(() => {
  const g = window.game
  return {
    step: g.missions.step,
    objective: g.missions.current?.text || null,
    inCar: g.activeChar.inVehicle === g.personalCar,
    driver: g.personalCar.driverSeat === g.activeChar,
    partnerInCar: g.partner.inVehicle === g.personalCar,
    fuel: g.personalCar.fuel,
    car: g.personalCar.spec.name
  }
})

await page.keyboard.down('KeyW')
await page.waitForTimeout(2200)
await page.keyboard.up('KeyW')
await page.waitForTimeout(500)

const afterDrive = await page.evaluate(() => {
  const g = window.game
  return {
    carX: +g.personalCar.pos.x.toFixed(2),
    carZ: +g.personalCar.pos.z.toFixed(2),
    speed: +g.personalCar.speed.toFixed(2),
    fuel: +g.personalCar.fuel.toFixed(2),
    step: g.missions.step
  }
})

await page.keyboard.press('KeyM')
await page.waitForTimeout(400)
const phone = await page.evaluate(() => ({
  open: !document.getElementById('phone').classList.contains('hidden'),
  cashText: document.getElementById('phoneCash')?.textContent || null
}))
await page.keyboard.press('Escape')
await page.waitForTimeout(300)
await page.keyboard.press('KeyF')
await page.waitForTimeout(800)
const afterExit = await page.evaluate(() => ({
  inCar: !!window.game.activeChar.inVehicle,
  visible: window.game.activeChar.group.visible
}))

console.log(JSON.stringify({ afterEnter, afterDrive, phone, afterExit, errors }, null, 2))
await browser.close()

